script:
(function () {
  'use strict';
  // Cool million: monthly compounding at (annual return / 12), savings added at the end of each
  // month, starting balance invested today. Today's-dollar values divide by (1 + inflation)^years.
  //   Balance after n months = P(1+i)^n + S((1+i)^n - 1)/i       (i = 0: P + S n)
  //   Monthly saving needed  = (T - P(1+i)^n) / (((1+i)^n - 1)/i)   (i = 0: (T - P)/n)
  //   Age at target: month-by-month simulation, capped at 100 years.
  //   "Target in today's dollars" option: the goal grows by (1 + inflation)^(months/12).
  // Verified (Node scratch test vs an independent Python closed-form check): $10,000 + $500/month
  //   at 7% from age 30 to 65 (420 months): $10,000 grows to $115,061.52 and the savings to
  //   $900,527.30, total $1,015,588.82; $1,000,000 is reached in month 418 (age 64.8).
  //   Saving needed for $1,000,000 by 65 = (1,000,000 - 115,061.52) / 1,801.05 = $491.34/month.
  //   0% return: ($1,000,000 - $10,000) / 420 = $2,357.14. $1,000,000 in 35 years at 3% inflation
  //   is worth $1,000,000 / 1.03^35 = $355,383 today; a today's-dollar target needs $1,498.46/month.
  //   Invalid input (target age before current age, blanks) shows an error and never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var MAX_MONTHS = 1200;

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function futureValue(p, s, i, n) {
    if (i === 0) return p + s * n;
    var g = Math.pow(1 + i, n);
    return p * g + s * (g - 1) / i;
  }

  function savingNeeded(target, p, i, n) {
    if (n <= 0) return NaN;
    var need = target - p * Math.pow(1 + i, n);
    if (need <= 0) return 0;
    return i === 0 ? need / n : need / ((Math.pow(1 + i, n) - 1) / i);
  }

  // Months until the balance reaches the target (which may grow with inflation); -1 if never.
  function monthsToTarget(target, p, s, i, infl) {
    var bal = p;
    if (bal >= target) return 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      bal = bal * (1 + i) + s;
      if (bal >= target * Math.pow(1 + infl, m / 12) - 1e-9) return m;
    }
    return -1;
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function cell(tr, text) {
    var td = document.createElement('td');
    td.textContent = text;
    tr.appendChild(td);
  }

  function update() {
    var age = num('cmAge'), targetAge = num('cmTargetAge'), p = num('cmCurrent'), s = num('cmMonthly'),
        rate = num('cmRate'), infl = num('cmInflation'), target = num('cmTarget');
    var real = document.getElementById('cmTargetType').value === 'real';
    var error = document.getElementById('cmError');
    var msg = '';
    if ([age, targetAge, p, s, rate, infl, target].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (age < 0 || age > 100 || targetAge > 120) msg = 'Enter ages from 0 to 120.';
    else if (targetAge <= age) msg = 'The target age must be later than your current age.';
    else if (p < 0 || s < 0) msg = 'Amounts cannot be negative.';
    else if (rate < 0 || rate > 50) msg = 'Enter a rate of return from 0 to 50%.';
    else if (infl < 0 || infl > 20) msg = 'Enter an inflation rate from 0 to 20%.';
    else if (target <= 0) msg = 'Enter a target above $0.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var i = rate / 100 / 12, f = infl / 100;
    var n = Math.round((targetAge - age) * 12);
    var years = n / 12;
    var deflator = Math.pow(1 + f, years);
    var goalAtTargetAge = real ? target * deflator : target;

    var balance = futureValue(p, s, i, n);
    var needed = savingNeeded(goalAtTargetAge, p, i, n);
    var months = monthsToTarget(target, p, s, i, real ? f : 0);

    set('cmTargetLabel', 'Age you reach ' + money0.format(target));
    if (months < 0) set('cmReachAge', 'Not within 100 years');
    else set('cmReachAge', (age + months / 12).toFixed(1));
    set('cmReachNote', months < 0 ? 'Save more each month or assume a higher return to get there.' :
        months === 0 ? 'You already have the target amount.' : 'In ' + duration(months) + ' with your current plan.');
    set('cmNeededLabel', 'Monthly saving needed by age ' + targetAge);
    set('cmNeeded', money.format(needed));
    set('cmBalanceLabel', 'Balance at age ' + targetAge);
    set('cmBalance', money0.format(balance));
    set('cmBalanceReal', money0.format(balance / deflator));
    set('cmTargetReal', real ? money0.format(goalAtTargetAge) : money0.format(target / deflator));
    set('cmTargetRealTerm', real ? 'Target in future dollars at ' + targetAge : 'What ' + money0.format(target) + ' at ' + targetAge + ' buys in today\'s dollars');
    set('cmGap', balance >= goalAtTargetAge ? 'On track: ' + money0.format(balance - goalAtTargetAge) + ' ahead of the target'
        : money0.format(goalAtTargetAge - balance) + ' short of the target');

    var body = document.getElementById('cmSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    var bal = p, contributed = p;
    for (var m = 1; m <= n; m++) {
      bal = bal * (1 + i) + s;
      contributed += s;
      if (m % 12 === 0 || m === n) {
        var tr = document.createElement('tr');
        var yrs = m / 12;
        cell(tr, m % 12 === 0 ? String(Math.round(age + yrs)) : (age + yrs).toFixed(1));
        cell(tr, money0.format(contributed));
        cell(tr, money0.format(bal - contributed));
        cell(tr, money0.format(bal));
        cell(tr, money0.format(bal / Math.pow(1 + f, yrs)));
        body.appendChild(tr);
      }
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
